import sys, os, zlib, hashlib, struct, subprocess, binascii
from collections import defaultdict

TYPES = {1:'commit',2:'tree',3:'blob',4:'tag',6:'ofs_delta',7:'ref_delta'}

def read_varint_size(buf, i):
    c = buf[i]; i += 1
    typ = (c >> 4) & 7
    size = c & 15
    shift = 4
    while c & 0x80:
        c = buf[i]; i += 1
        size |= (c & 0x7f) << shift
        shift += 7
    return typ, size, i

def read_ofs(buf, i):
    c = buf[i]; i += 1
    off = c & 0x7f
    while c & 0x80:
        c = buf[i]; i += 1
        off = ((off + 1) << 7) | (c & 0x7f)
    return off, i

def read_delta_varint(d, i):
    v = 0; shift = 0
    while True:
        c = d[i]; i += 1
        v |= (c & 0x7f) << shift
        shift += 7
        if not (c & 0x80): break
    return v, i

def apply_delta(base, delta):
    i = 0
    bsz, i = read_delta_varint(delta, i)
    rsz, i = read_delta_varint(delta, i)
    if bsz != len(base):
        raise ValueError(f"base size mismatch {bsz} != {len(base)}")
    out = bytearray()
    while i < len(delta):
        cmd = delta[i]; i += 1
        if cmd & 0x80:
            off = 0; sz = 0
            if cmd & 0x01: off |= delta[i]; i += 1
            if cmd & 0x02: off |= delta[i] << 8; i += 1
            if cmd & 0x04: off |= delta[i] << 16; i += 1
            if cmd & 0x08: off |= delta[i] << 24; i += 1
            if cmd & 0x10: sz |= delta[i]; i += 1
            if cmd & 0x20: sz |= delta[i] << 8; i += 1
            if cmd & 0x40: sz |= delta[i] << 16; i += 1
            if sz == 0: sz = 0x10000
            if off + sz > len(base): raise ValueError("copy out of range")
            out += base[off:off+sz]
        elif cmd:
            out += delta[i:i+cmd]; i += cmd
        else:
            raise ValueError("delta cmd 0")
    if len(out) != rsz: raise ValueError(f"result size mismatch {len(out)} != {rsz}")
    return bytes(out)

def objsha(typ, content):
    return hashlib.sha1(f"{typ} {len(content)}".encode() + b"\x00" + content).hexdigest()

class Pack:
    def __init__(self, packpath, idxpath, name):
        self.name = name
        self.data = open(packpath,'rb').read()
        out = subprocess.run(['git','show-index'], input=open(idxpath,'rb').read(), capture_output=True, check=True).stdout.decode()
        ents = []
        for line in out.splitlines():
            off, sha, crc = line.split()
            ents.append((int(off), sha, int(crc.strip('()'),16)))
        ents.sort()
        self.entries = ents
        self.by_sha = {sha:(off,crc) for off,sha,crc in ents}
        self.by_off = {off:sha for off,sha,crc in ents}
        self.info = {}  # sha -> dict
        self.parse_all()

    def parse_all(self):
        d = self.data
        magic, ver, n = d[:4], struct.unpack('>I', d[4:8])[0], struct.unpack('>I', d[8:12])[0]
        self.header = (magic, ver, n)
        ends = [off for off,_,_ in self.entries[1:]] + [len(d)-20]
        for (off, sha, crc), end in zip(self.entries, ends):
            rec = dict(off=off, end=end, sha=sha, crc_idx=crc)
            rec['crc_ok'] = (binascii.crc32(d[off:end]) & 0xffffffff) == crc
            try:
                typ, size, i = read_varint_size(d, off)
                rec['type'] = TYPES.get(typ, f'?{typ}')
                rec['size'] = size
                if typ == 6:
                    rel, i = read_ofs(d, i)
                    rec['base_off'] = off - rel
                    rec['base'] = self.by_off.get(off - rel)
                elif typ == 7:
                    rec['base'] = d[i:i+20].hex(); i += 20
                rec['data_start'] = i
                dobj = zlib.decompressobj()
                try:
                    raw = dobj.decompress(d[i:end])
                    tail = dobj.unused_data
                    rec['inflate_ok'] = dobj.eof and len(raw) == size
                    rec['consumed'] = (end - i) - len(tail)
                    rec['raw'] = raw
                    if not dobj.eof: rec['inflate_err'] = 'stream not finished within entry'
                    elif len(raw) != size: rec['inflate_err'] = f'size {len(raw)} != {size}'
                except Exception as e:
                    rec['inflate_ok'] = False
                    rec['inflate_err'] = str(e)
            except Exception as e:
                rec['type'] = '?'; rec['inflate_ok'] = False; rec['inflate_err'] = f'header: {e}'
            self.info[sha] = rec

class Store:
    def __init__(self):
        self.loose = {}
        self.packs = []
        self.cache = {}
    def add_loose_dir(self, root):
        for dn in os.listdir(root):
            if len(dn) != 2: continue
            for fn in os.listdir(os.path.join(root, dn)):
                sha = dn+fn
                try:
                    raw = zlib.decompress(open(os.path.join(root,dn,fn),'rb').read())
                    hdr, _, body = raw.partition(b'\x00')
                    typ, _, ln = hdr.partition(b' ')
                    if int(ln) == len(body) and hashlib.sha1(raw).hexdigest() == sha:
                        self.loose[sha] = (typ.decode(), body)
                except Exception:
                    pass
    def get(self, sha, exclude_pack=None, depth=0):
        if sha in self.cache: return self.cache[sha]
        if depth > 200: return None
        if sha in self.loose:
            self.cache[sha] = self.loose[sha]; return self.loose[sha]
        for p in self.packs:
            if p is exclude_pack: continue
            r = self.get_from_pack(p, sha, depth)
            if r: 
                self.cache[sha] = r; return r
        return None
    def get_from_pack(self, p, sha, depth):
        rec = p.info.get(sha)
        if not rec or not rec.get('inflate_ok'): return None
        t = rec['type']
        if t in ('commit','tree','blob','tag'):
            content = rec['raw']
            if objsha(t, content) != sha: 
                rec['sha_mismatch'] = True
                return None
            return (t, content)
        base_sha = rec.get('base')
        if not base_sha: return None
        # prefer in-pack base, fall back to anything
        base = None
        brec = p.info.get(base_sha)
        if brec: base = self.get_from_pack(p, base_sha, depth+1)
        if base is None:
            base = self.get(base_sha, depth=depth+1)
            if base is not None: rec['base_from_elsewhere'] = True
        if base is None: return None
        try:
            content = apply_delta(base[1], rec['raw'])
        except Exception as e:
            rec['delta_err'] = str(e); return None
        if objsha(base[0], content) != sha:
            rec['sha_mismatch'] = True; return None
        return (base[0], content)

repo = sys.argv[1]
store = Store()
store.add_loose_dir(os.path.join(repo,'objects'))
good = Pack(os.path.join(repo,'objects/pack/pack-dc1a3d5e56cdb2c83174659a7deaaca10d01e520.pack'), '/tmp/idxtest/pack-dc1a3d5e56cdb2c83174659a7deaaca10d01e520.idx', 'dc1a')
bad  = Pack(os.path.join(repo,'objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.pack'), os.path.join(repo,'objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.idx'), '0edb')
store.packs = [good, bad]

print("good pack header:", good.header, "entries:", len(good.entries))
print("bad  pack header:", bad.header, "entries:", len(bad.entries))
print("loose valid:", len(store.loose))
print()
print("=== dc1a pack: crc/inflate failures ===")
for off,sha,crc in good.entries:
    r = good.info[sha]
    if not r['crc_ok'] or not r['inflate_ok']:
        print(sha, r['off'], r['type'], r.get('inflate_err'))
print("(end)")
print()
print("=== 0edb pack: per-entry status (only non-OK rows shown; OK = crc ok & inflate ok) ===")
nbad = 0
for off,sha,crc in bad.entries:
    r = bad.info[sha]
    if not (r['crc_ok'] and r['inflate_ok']):
        nbad += 1
        print(f"{sha} off={off:6d} end={r['end']:6d} type={r['type']:9s} size={r.get('size')} crc_ok={r['crc_ok']} inflate_ok={r['inflate_ok']} err={r.get('inflate_err')} base={r.get('base')}")
print("non-OK entries:", nbad)
print()
# Resolve everything
all_shas = set(store.loose) | set(good.info) | set(bad.info)
unrec = []
rec_src = defaultdict(int)
for sha in sorted(all_shas):
    r = store.get(sha)
    if r is None: unrec.append(sha)
print("total distinct shas across sources:", len(all_shas))
print("recoverable:", len(all_shas)-len(unrec), " unrecoverable:", len(unrec))
print()
print("=== unrecoverable shas (with where they appear) ===")
for sha in unrec:
    where = []
    if sha in good.info: where.append('dc1a')
    if sha in bad.info:
        r = bad.info[sha]; where.append(f"0edb(off={r['off']},type={r['type']},crc_ok={r['crc_ok']},inflate_ok={r['inflate_ok']},base={r.get('base')},delta_err={r.get('delta_err')},sha_mismatch={r.get('sha_mismatch')})")
    lp = os.path.join(repo,'objects',sha[:2],sha[2:])
    if os.path.exists(lp): where.append('loose-corrupt')
    print(sha, ' '.join(where))
print()
print("=== 0edb entries whose base had to come from elsewhere ===")
for sha,r in bad.info.items():
    if r.get('base_from_elsewhere'): print(sha, '<-', r.get('base'))
print()
# referenced-but-absent check across recoverable objects
referenced = defaultdict(set)
for sha in all_shas:
    r = store.get(sha)
    if not r: continue
    t, c = r
    if t == 'commit':
        for line in c.split(b'\n'):
            if line == b'': break
            k, _, v = line.partition(b' ')
            if k in (b'tree', b'parent'): referenced[v.decode()].add(('commit', sha))
    elif t == 'tree':
        i = 0
        while i < len(c):
            j = c.index(b'\x00', i)
            mode, _, name = c[i:j].partition(b' ')
            s = c[j+1:j+21].hex(); i = j+21
            referenced[s].add(('tree', sha))
    elif t == 'tag':
        for line in c.split(b'\n'):
            if line == b'': break
            k, _, v = line.partition(b' ')
            if k == b'object': referenced[v.decode()].add(('tag', sha))
missing_ref = sorted(s for s in referenced if store.get(s) is None)
print("=== referenced by a recoverable object but NOT recoverable:", len(missing_ref), "===")
for s in missing_ref:
    print(s, sorted(referenced[s])[:3])
import pickle
pickle.dump({'unrec':unrec,'missing_ref':missing_ref}, open('/tmp/tools/scan.pkl','wb'))
