import sys, zlib, hashlib, os, itertools, time
repo='/app/repo.git'
bad = ["34122478b3a70aba0dc15d5fe871a09f40234270","6e51414cbc4506538265c702c40710e33e16a695","b10242c6f02a2ad627f772aa0a930370863f5bf8","bec25078095e3cede8a7ee84c40b7ec6bebe6e1b","e2e5e720516f652120ddc8dce745438eba10bc75","e8f1d4475ab54db256d43f0f25775e1b0ee08174"]
def check(buf, sha):
    try:
        data = zlib.decompress(buf)
    except Exception:
        return None
    return data if hashlib.sha1(data).hexdigest()==sha else None
results={}
for sha in bad:
    raw = bytearray(open(f"{repo}/objects/{sha[:2]}/{sha[2:]}",'rb').read())
    t=time.time(); found=None; tries=0
    for i in range(len(raw)):
        orig=raw[i]
        for v in range(256):
            if v==orig: continue
            raw[i]=v; tries+=1
            d=check(bytes(raw), sha)
            if d is not None:
                found=(i,orig,v,d); break
        raw[i]=orig
        if found: break
