import collections
vers=collections.defaultdict(list)
for s,(f,m) in commits.items():
    for mode,name,sha in tree_entries(K[f['tree'][0]][1]):
        if name in ('VERSION','pyproject.toml'): vers[(name,sha)].append(s)
for (name,sha),cs in sorted(vers.items(), key=lambda kv: min(when(c) for c in kv[1])):
    cs=sorted(cs,key=when); c=K[sha][1]
