print()
# release commits and their parents' committer times
for s,(f,m) in sorted(commits.items(), key=lambda kv: when(kv[0])):
    subj=m.splitlines()[0]
    if subj.startswith('Release ') or 'tag' in subj.lower() or 'release' in subj.lower():
        par=f['parent']; pt=[str(when(p)) if p in commits else p[:8]+'?' for p in par]
        print(f"{s[:10]} ct={when(s)} {f['committer'][0]} {subj!r} parents={[p[:8] for p in par]} parent_ct={pt}")
